"""Actual passive AX readback recording test; inputs are generated by a separate Runtime, not a human."""
import argparse,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from pathlib import Path
import time,json
from bokkio.audit import AuditStore
from bokkio.runtime import Runtime
from bokkio.sdk import Client
from bokkio.manual_recording import ManualRecorder
from bokkio.app_launch import installed_running_apps
from bokkio.runtime_workflow import runtime_snapshot
from bokkio.workflow import save_json
parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--fixture',type=Path,required=True);parser.add_argument('--output',type=Path,required=True);parser.add_argument('--approve-owned-fixture',action='store_true');args=parser.parse_args()
if not args.approve_owned_fixture:parser.error('Explicit owned disposable fixture authorization is required')
app=next(a for a in installed_running_apps()if a['name']=='BokkioWorkflowLab' and a['path']==str(args.fixture.resolve()));pid=app['pid'];title='Bokkio Workflow Lab'
root=args.output;root.mkdir(parents=True,exist_ok=False,mode=0o700)
rclient=Client(Runtime(root/'recorder',{'apps':[str(pid)],'write':False}));rclient.open();actor=Client(Runtime(root/'actor',{'apps':[str(pid)],'write':True,'require_approval':False}));actor.open()
def set_value(value):
 r,s=runtime_snapshot(actor,pid,title);n=next(n for n in s['windows']if n['role']=='text_field' and n['name']=='Workflow Input')
 result=actor.call('desktop.act',{'app':str(pid),'window':title,'observation_id':r['result']['observation_id'],'ref':n['ref'],'action':'set_value','value':value});assert result['status'] in {'verified','executed'},result
rec=ManualRecorder(rclient,[app])
try:
    rec.start();time.sleep(.6);set_value('readback 中文 one')
    deadline=time.monotonic()+8
    while not rec.doc['steps'] and time.monotonic()<deadline:time.sleep(.1)
    one=bool(rec.doc['steps']) and rec.doc['steps'][-1]['arguments']['value']=='readback 中文 one'
    rec.pause();before=json.dumps(rec.doc['steps']);set_value('paused-not-recorded');time.sleep(.5);paused=rec.process is None and before==json.dumps(rec.doc['steps'])
    rec.start();time.sleep(.6);set_value('readback 中文 two');deadline=time.monotonic()+8
    while len(rec.doc['steps'])<2 and time.monotonic()<deadline:time.sleep(.1)
    resumed=len(rec.doc['steps'])==2 and rec.doc['steps'][-1]['arguments']['value']=='readback 中文 two'
finally:
    rec.stop();actor.call('session.close')
checks=[{'case':'actual_passive_AX_value_readback','passed':one},{'case':'pause_terminates_capture_and_excludes_changes','passed':paused},{'case':'resume_preserves_pause_boundary','passed':resumed},{'case':'recorder_zero_dispatched_writes','passed':not any(e['data'].get('write')for e in rclient.runtime.store.query(kind='execution.intent'))}]
save_json(root/'report.json',{'scope':'actual_native_passive_readback_with_separate_Runtime_input_generator_not_human_or_pointer_capture','passed':sum(c['passed']for c in checks),'total':len(checks),'checks':checks,'issues':rec.issues,'physical_mouse_capture_tested':False})
print(json.dumps({'passed':sum(c['passed']for c in checks),'total':len(checks),'issues':rec.issues}))

raise SystemExit(0 if all(c["passed"] for c in checks) else 1)
